mapper.select:
/* selectSubOrg - Lee JiSeob */
SELECT C.SUB_ORG_ID, C.SUB_ORG_NAME, C.ORG_CODE, (SELECT D.INST_NM FROM SAA000 D /* 통합기관 */ WHERE D.INST_NO = C.ORG_CODE) AS ORG_NAME, C.ENG_CTPV_NM, (SELECT MAX(E.CTPV_NM) FROM SAA020 E WHERE E.ENG_CTPV_NM = C.ENG_CTPV_NM) AS CTPV_NM, C.CTPV_SGG_CD, (SELECT MAX(F.SGG_NM) FROM SAA020 F WHERE F.SGG_CD = C.CTPV_SGG_CD) AS SGG_NM
FROM SUB_ORGANIZATION C
WHERE C.ORG_CODE = #{orgCode}
AND C.ENG_CTPV_NM = #{engCtpvNm}
AND C.CTPV_SGG_CD = #{ctpvSggCd}
AND C.DEL_YN = 'N'
ORDER BY C.INDCT_ORD, C.SUB_ORG_ID
